    ('00c2b26f-d007-4c02-a5da-403f14f8daa5'::uuid, 'period_name', NULL, '500 - 1000 AD', 'fields-wd3-2026-10-02b-s001:00c2b26f-d007-4c02-a5da-403f14f8daa5:period_name', 'fields-wd3-2026-10-02b-s001 (wd3-derive-period-name): period_start 900 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(900) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0254)", "decision": "replace", "status": "MISSING", "reasoning": "The mincetur national inventory record for Sitio Arqueologico Monumental Huamanmarca - the same site as Wamanmarka, Lima, cited by the English Wikipedia article - states that archaeologist Maria Espinoza dated its construction to the Late Intermediate period, 900 to 1400 years after Christ. The start of the site is therefore 900 AD.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
